// 书签，顺序相同
function handlerRegex() {
    return () => {
        let novelIds = []
        let matched = result.match(RegExp(/\/novel\/show\.php\?id=\d{5,}/gm))
        for (let i in matched) {
            let novelId = matched[i].match(RegExp(/\d{5,}/))[0]
            if (novelIds.indexOf(novelId) === -1) {
                novelIds.push(novelId)
            }
