@js:
s = [];
push = (t, u, x) => s.push({ title: t, url: u, style: { layout_flexGrow: 1, layout_flexBasisPercent: x } });

const getSafeVariable = () => {
    try {
        const varStr = source.getVariable();
        if (!varStr || varStr.trim() === "" || varStr === "null") return ["", "", "", ""];
        const parsed = JSON.parse(varStr);
        while (parsed.length < 4) parsed.push("");
        return parsed;
    } catch (e) {
        return ["", "", "", ""];
    }
};

const current = getSafeVariable();
const getVarCode = `(${getSafeVariable.toString()})()`;

const doc = org.jsoup.Jsoup.parse(java.ajax(source.key));
doc.select('.whitespace-pre-line > div:nth-child(3) > a:first-child').forEach(fl => {
    const href = fl.attr('href');
    const text = fl.text();

    const setUrlJs = `<js>
        let o = ${getVarCode};
        o[0] = '${href}';
        source.setVariable(JSON.stringify(o));
        java.longToast('已设置地址: ${href}, 刷新生效');
        java.reload();
    </js>`;
    push(href, setUrlJs, 1);
});

push(`当前地址：${current[0] || "https://18mh.net"}`, 1);

const processOptions = (list, idx, prefix, defaultTxt) => {
    const map = {};
    list.forEach(([name, param]) => map[param] = name);
    push(`${prefix}${map[current[idx]?.trim()] || defaultTxt}`, "", 1);
    list.forEach(([name, param]) => push(
        name,
        `<js>
            let o = ${getVarCode};
            o[${idx}] = '${param}';
            source.setVariable(JSON.stringify(o));
            java.longToast('已选择 ${name}, 刷新生效');
            java.reload();
        </js>`
        , 0.2));
};

